"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': "The Edinburgh's Old Town Letters", 'author': 'Signature original', 'genre': 'Tudor Courts', 'chapters': [{'n': 1, 'title': 'The Discovery', 'text': "But a railway ticket would not be ignored. That night, by gaslight, Margaret Ellison examined it: the handwriting, the seal, the date — twenty years gone. And the name. The name that the factory boss had paid good money to bury.\n\nBy morning Margaret Ellison had decided. a railway ticket would not stay hidden. Whatever the factory boss did, whatever Edinburgh's Old Town whispered — courage in every age, and the truth would have its day.\n\nThe a railway ticket came to Margaret Ellison on a rainy Thursday in Edinburgh's Old Town, tucked in a solicitor's envelope smelling of dust and secrets. Margaret Ellison was not, by nature, a curious person. Curiosity, in Edinburgh's Old Town, was a luxury for those with full larders."}, {'n': 2, 'title': 'Inquiries', 'text': "the seamstress proved unexpectedly brave, carrying messages, watching doors, learning the servants' gossip that the masters never hear. 'The downstairs knows everything,' the seamstress said. 'Upstairs just pays for it.'\n\nEach answer was a thread, and the threads wove the factory boss's tapestry: the mill, the accident, the silenced witnesses, the money that flowed like a dirty river through Edinburgh's Old Town. a railway ticket was the loose end.\n\nThe daguerreotype — no, a railway ticket — revealed its last secret then: a face in the background, a witness the factory boss had missed. Margaret Ellison found the address. The game, as the young people say, was afoot — though in Edinburgh's Old Town, they said it more politely."}, {'n': 3, 'title': 'The Witness', 'text': "The magistrate was the factory boss's man; the papers were the factory boss's papers. But a railway ticket was Margaret Ellison's, and the witness was real, and the truth — Margaret Ellison clung to this — the truth is stubborn in any century.\n\nthe factory boss struck that night: a break-in, a fire set to frighten, a thug with a message written in bruises. the seamstress took the worst of it and joked through split lips. Margaret Ellison wept and planned.\n\nMargaret Ellison promised protection — a promise that felt like a stone in the pocket, heavy and necessary. the seamstress arranged the safe room, the food, the watchers. Edinburgh's Old Town's poor take care of their own; they always have."}, {'n': 4, 'title': 'The Reckoning', 'text': "the factory boss laughed — then didn't. The evidence was a chain, each link forged: a railway ticket, the register, the witness, the ledger page the seamstress had risked everything to copy. Link by link, it held.\n\nMargaret Ellison stood in the emptying hall with a railway ticket and felt not triumph but tiredness, and under it, peace. courage in every age. It had cost plenty. It was worth it.\n\nIt came to a head at the assembly rooms, in front of all Edinburgh's Old Town: Margaret Ellison stood and spoke, with a railway ticket held high and the witness beside them. The gaslight seemed to lean in to listen."}, {'n': 5, 'title': 'Restoration', 'text': "Margaret Ellison went back to ordinary life, which turned out to be extraordinary enough: work, friends, Sundays, the small heroisms of kindness. a railway ticket had taught them that history is just people, choosing.\n\nthe seamstress married the vicar's son — or daughter; Edinburgh's Old Town gossiped happily either way — and named their first child after Margaret Ellison, who pretended to mind and didn't.\n\ncourage in every age — Margaret Ellison had it carved, finally, on no monument at all, just lived it, in Edinburgh's Old Town, in every ordinary, extraordinary day."}, {'n': 6, 'title': 'Coda: The Drawer', 'text': "the factory boss is a name in the records, a caution. Edinburgh's Old Town is a place where the mills run fair and the magistrate is honest, mostly, which is as much as any age can ask.\n\ncourage in every age. In Edinburgh's Old Town, in every place, in every age. The end — which is to say, the beginning.\n\nthe seamstress visits with the children, who are told the story as a fairy tale — which, Margaret Ellison reflects, is what all true stories become, if they're lucky."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

